def get_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def solve():
    successful_cases = []
    # Range: n < 200, so up to 199
    for n in range(1, 200):
        divs = get_divisors(n)
        tau_n = len(divs)

        # Check conditions: 5 <= tau(n) <= 12
        if 5 <= tau_n <= 12:
            # Need at least 5 divisors for a, b, c to exist (d2, d3, d5)
            if tau_n >= 5:
                # Divisors list is 0-indexed: [d1, d2, d3, d4, d5, ...]
                # d1 = divs[0] = 1
                # a is the second smallest (d2) -> index 1
                # b is the third smallest (d3) -> index 2
                # c is the fifth smallest (d5) -> index 4

                a = divs[1]
                b = divs[2]
                c = divs[4]

                # Check the simplified equation: ab + ac + bc = n
                if a * b + a * c + b * c == n:
                    successful_cases.append((n, tau_n))

    print("Successful cases (n, tau(n)):")
    for n, tau in successful_cases:
        print(f"{n}, {tau}")

solve()
